  if(/(?:상담(?: 받는)? 중|상담 대기|면접)/.test(line))return '💬';
  if(/급하게 창 닫는 중|인스타/.test(line))return '📱';
  if(/커피|카페|Coffee/i.test(line))return '☕';
  if(/점심|식사|도시락|밥 먹|아침 먹|저녁 먹/.test(line))return '🍱';
  if(/옥상|정원|테라스/.test(line))return '🌿';
